  ('9b058a7a-11a7-47ae-9d13-88b5458a1c75'::uuid, 'Mavi Ceket Pantolon Takım', 'Şık ve modern kesimiyle dikkat çeken bu ceket, her kombininize sofistike bir dokunuş katacak. Ön kısmındaki metal düğme detayları ve kolsuz tasarımıyla tarzınızı tamamlayın. Bu mavi yüksek bel pantolon, modern ve şık bir görünüm sunar. Bol paça kesimi ile rahatlığı ve zarafeti bir araya getirir.', null, 'available', 'fashion', 4, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb, '{"L":1,"M":1,"S":1,"XL":0,"XS":1,"2XL":0,"3XL":0}'::jsonb, '{"color":"Mavi","setItems":[{"chips":{"fit":"Regular","hem":null,"rise":null,"length":"Crop","sleeves":"Kolsuz","neckline":"Polo yaka","decollete":"Yok"},"family":"ust-giyim","category":"ceket"},{"chips":{"fit":"Regular","hem":"Bol","rise":"Normal bel","length":"Normal","sleeves":null,"neckline":null,"decollete":"Yok"},"family":"alt-giyim","category":"pantolon"}],"aiModelId":"studio:selin","uploadKind":"takim","colorGroupId":"4c4c3ecd-f1c4-4e3b-8fca-6151c1b165c9","colorSiblingIds":["5d28b0a1-7a7e-4b06-a3e0-711a5f66b3c8","b1d3b265-66d4-4e25-ac00-4a50c4938dd0","9b058a7a-11a7-47ae-9d13-88b5458a1c75"],"lifestyleModelIds":["studio:selin","studio:selin"]}'::jsonb, '["https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/f568c39a-1c65-4932-b171-b8bb0c4658ea.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/2bfcd69a-0e8b-43a7-b418-3fd2643695a7.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/d3739f29-12b4-4d89-bd4f-8bcd99a34fa6.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/eee612af-38a0-4ac1-ae7d-a3cd3be000c5.webp"]'